fn fixed_claims() -> JwtClaims {
    let mut claims = JwtClaims::new("legacy-user");
    claims.iat = Some(1_700_000_000);
    claims.exp = Some(2_524_608_000);
    claims.nbf = Some(1_700_000_000);
    claims
}

#[test]
fn legacy_hs_tokens_verify_and_new_tokens_match() {
    for &(algorithm, legacy_token) in LEGACY_TOKENS {
        let manager = JwtManager::with_algorithm("legacy-test-key", algorithm)
            .set_issuer("legacy-issuer")
            .set_audience("legacy-audience");
        let claims = manager
            .validate(legacy_token)
            .unwrap_or_else(|error| panic!("{algorithm:?}: {error:?}"));
        assert_eq!(claims.login_id, "legacy-user");
        assert_eq!(claims.iss.as_deref(), Some("legacy-issuer"));
        assert_eq!(claims.aud.as_deref(), Some("legacy-audience"));
        assert_eq!(manager.generate(&fixed_claims()).unwrap(), legacy_token);
        assert!(
            manager
                .clone()
                .set_issuer("wrong")
                .validate(legacy_token)
                .is_err()
        );
        assert!(
            manager
                .clone()
                .set_audience("wrong")
                .validate(legacy_token)
                .is_err()
        );
    }
}

#[test]
fn expiry_and_asymmetric_secret_errors_remain() {
    let manager = JwtManager::new("legacy-test-key");
    let mut expired = fixed_claims();
    expired.exp = Some(1_700_000_001);
    let token = manager.generate(&expired).unwrap();
    assert!(matches!(
        manager.validate(&token),
        Err(SaTokenError::TokenExpired)
    ));

    for algorithm in [
        JwtAlgorithm::RS256,
        JwtAlgorithm::RS384,
        JwtAlgorithm::RS512,
        JwtAlgorithm::ES256,
        JwtAlgorithm::ES384,
    ] {
        let result =
            JwtManager::with_algorithm("legacy-test-key", algorithm).generate(&fixed_claims());
        assert!(
            matches!(result, Err(SaTokenError::InvalidToken(message)) if message == "Failed to generate JWT: InvalidAlgorithm")
        );
    }
}
